// Normalize any entry (webhook / manual mock / schedule) into a safe envelope.
// Generates missing IDs, builds idempotency_key, validates, and classifies routing.
const src = $json || {};
const raw = src.body ? src.body : src;
const mock = raw._mock || src._mock || {};

function rid(p){ return p + Math.random().toString(36).slice(2,10) + Date.now().toString(36); }

const source_system = raw.source_system || '';
const event_type = raw.event_type || '';
const entity_family = (raw.entity_family || '').toString().toLowerCase();
const entity_id = raw.entity_id || '';
const source_event_id = raw.source_event_id || '';

const KNOWN_FAMILIES = [
  'business','product','raw_material','supplier','production','qc','inventory',
  'sales','order','payment','finance','operations','approval','ai','knowledge',
  'website','member','analytics','security'
];
const HIGH_RISK = ['refund','payment','purchase','formula_release','inventory_adjustment','publish','permission_change','delete','disclose_sensitive'];

// Channel classification
let channel = 'unsupported_request';
if (event_type === 'health_check' || src.__source === 'schedule') channel = 'health_check';
else if (event_type === 'agent_chat') channel = 'agent_chat';
else if (KNOWN_FAMILIES.indexOf(entity_family) !== -1) channel = 'business_event';
else channel = 'unsupported_request';

// Validation (reject malformed / unauthenticated / duplicate safely; unsupported handled by its own branch)
const warnings = [];
const authenticated = raw.authenticated === true || channel === 'health_check';
const malformed = channel !== 'health_check' && (!source_system || !event_type || !entity_id);
const duplicate = mock.duplicate === true;
if (malformed) warnings.push('malformed: missing required field(s)');
if (!authenticated) warnings.push('unauthenticated request');
if (duplicate) warnings.push('duplicate idempotency_key');
if (channel === 'unsupported_request') warnings.push('unsupported event_type');

const valid = !malformed && authenticated && !duplicate;
let reason = 'ok';
if (malformed) reason = 'MALFORMED';
else if (!authenticated) reason = 'UNAUTHENTICATED';
else if (duplicate) reason = 'DUPLICATE';
else if (channel === 'unsupported_request') reason = 'UNSUPPORTED';

const requires_approval = HIGH_RISK.indexOf((raw.action||'').toString()) !== -1 || mock.high_risk === true;

const idempotency_key = [source_system, event_type, entity_id, source_event_id].join('|');

const envelope = {
  meta: {
    correlation_id: raw.correlation_id || rid('cor_'),
    event_id: raw.event_id || rid('evt_'),
    idempotency_key: idempotency_key,
    source_system: source_system,
    event_type: event_type,
    schema_version: '1.0',
    received_at: $now.toISO(),
  },
  actor: {
    actor_type: raw.actor_type || 'unknown',
    actor_id: raw.actor_id || '',
    display_name: raw.display_name || '',
  },
  entity: {
    entity_type: raw.entity_type || '',
    entity_id: entity_id,
    entity_family: entity_family,
    status: raw.status || '',
    payload: raw.payload || {},
  },
  control: {
    environment: 'TEST',
    dry_run: true,
    priority: raw.priority || 'normal',
    requires_approval: requires_approval,
    retry_count: 0,
    sim_outcome: mock.transient_error === true ? 'transient_error' : 'none',
  },
  channel: channel,
  validation: { valid: valid, reason: reason, duplicate: duplicate, warnings: warnings },
  test_case: mock.case || null,
};

return { json: envelope };

// Robust audit builder: preserves the normalized envelope and avoids raw-JSON expression failures.
const input = $json ?? {};
const meta = input.meta ?? {};
const validation = input.validation ?? {};
const control = input.control ?? {};

return {
  json: {
    ...input,
    audit: {
      stage: 'received+validated',
      correlation_id: meta.correlation_id ?? null,
      event_id: meta.event_id ?? null,
      idempotency_key: meta.idempotency_key ?? null,
      source_system: meta.source_system ?? null,
      event_type: meta.event_type ?? null,
      channel: input.channel ?? 'unsupported_request',
      valid: validation.valid === true,
      reason: validation.reason ?? 'UNKNOWN',
      requires_approval: control.requires_approval === true,
      environment: control.environment ?? 'TEST',
      dry_run: control.dry_run !== false,
      logged_at: $now.toISO(),
    },
  },
};

// Classify outcome. Retry ONLY transient errors (429/5xx/timeout), max 3 retries.
// Never retry authentication, invalid data, rejected approval, or missing configuration.
const RETRYABLE_CODES = [429, 500, 502, 503, 504];
const MAX_RETRIES = 3;
const j = $json ?? {};
const ctl = { ...(j.control ?? {}) };
const attempts = Number.isFinite(Number(ctl.retry_count)) ? Number(ctl.retry_count) : 0;
const isTransient =
  ctl.sim_outcome === 'transient_error' ||
  RETRYABLE_CODES.includes(Number(j.error_code)) ||
  j.timeout === true ||
  j.status === 'TRANSIENT_ERROR';

let outcome_class = 'success';

if (isTransient) {
  if (attempts < MAX_RETRIES) {
    ctl.retry_count = attempts + 1;
    outcome_class = 'retryable';
  } else {
    outcome_class = 'permanent';
  }
} else if (j.status === 'CONFIGURATION_REQUIRED' || j.configuration_required === true) {
  outcome_class = 'config';
}

j.control = ctl;
j.outcome_class = outcome_class;
return { json: j };

