// TEST-safe duplicate protection using workflow static data. Replace with a durable Data Table/DB before production scale.
const item = $json ?? {};
const store = $getWorkflowStaticData('global');
store.lineSeen = store.lineSeen ?? {};
const now = Date.now();
const ttlMs = 24 * 60 * 60 * 1000;
for (const [key, timestamp] of Object.entries(store.lineSeen)) {
  if (now - Number(timestamp) > ttlMs) delete store.lineSeen[key];
}
const key = item.source_event_id || item.event_id || item.correlation_id;
const duplicate = Boolean(key && store.lineSeen[key]);
if (key && !duplicate) store.lineSeen[key] = now;
return { json: { ...item, line_duplicate: duplicate, idempotency_key: ['line_oa', item.event_type, item.entity_id, key].join('|') } };

